  "summary": [
    "Anchored on the IOM Missing Migrants Project reference class, which historically records Mediterranean deaths well above 1,000 per year.",
    "As of February 2026, about 606 deaths/missing have occurred, implying a pace that, if sustained, plausibly exceeds 1,000 by May 2026.",
    "Historical baselines (2024–2025) show annual tolls around 2,100–2,400, supporting the plausibility of reaching 1,000 by May under current momentum.",
    "Calibrated posterior probability is 95% with some residual uncertainty due to data gaps, weather risks, and possible policy/SAR changes."
  ],
  "confidence": "high",
  "narrative": "Starting from a high baseline anchored in the long-run Mediterranean death toll, the February 2026 pace (~606 deaths) suggests that a total above 1,000 by May is highly plausible if the trend persists. The 95% posterior reflects strong evidence but acknowledges uncertainty from reporting gaps and external risk factors.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Why this reference class and anchor probability were chosen: The reference class is the IOM Missing Migrants Project's annual Mediterranean death toll, where counts routinely exceed 1,000 and recent year totals (2024–2025) show elevated mortality, justifying a strong anchor around 0.85."
    },
    "factor_updates": [
      {
        "factor": "Current pace in 2026 (through February): deaths reached about 606 by February",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by end-February 2026 implies a pace that could surpass 1,000 by May if the rate remains similar or higher."
      },
      {
        "factor": "Historical baseline: Mediterranean toll typically exceeds 1,000 per year",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Recent years show ~2,100–2,400 deaths annually, making a 1,000-by-May outcome plausible under favorable momentum."
      },
      {
        "factor": "Severe weather events increasing fatalities in early 2026",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storms and rough seas have historically raised near-term fatalities, supporting higher counts in early 2026."
      },
      {
        "factor": "Data gaps / undercount risk due to funding cuts and limited access",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Underreporting could mean the toll is even higher than observed, reinforcing the case for a higher end of the range."
      },
      {
        "factor": "Policy crackdown and reduced rescue capacity in EU/Italy",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter disembarkation policies and reduced SAR capacity can elevate fatalities, pushing the total toward or beyond 1,000 by May."
      }
    ],
    "synthesis_rationale": "Starting from an 0.85 anchor, the five factor updates collectively tilt the probability upward with strong emphasis on early-2026 pace and high annual baselines. While correlated, the updates reinforce a high-likelihood path to 1,000+ deaths by May, and the 95% posterior reflects calibration for this combination of evidence and acknowledged uncertainty."
  }
}

