      },
      {
        "factor": "Historical baseline: annual toll routinely >1,000 (2025 ~2,108; 2024 ~2,452)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Strong historical momentum toward 1,000+ fatalities annually supports plausibility of 1,000 by May with a sustained elevated pace."
      },
      {
        "factor": "Seasonality / spring risk uptick",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring months typically see continued crossing attempts and risk, reinforcing the possibility of more deaths in the near term."
      },
      {
        "factor": "Data collection constraints / undercount risk",
        "direction": "up",
